/// <summary>
/// Read &amp; Write Module for Direction
/// Check added by CKY , 7-OCT-1996
/// </summary>
internal class RWStepGeom_RWDirection
{
    public RWStepGeom_RWDirection()
    {
    }

    public void ReadStep(StepData_StepReaderData data, int num, Interface_Check ach, StepGeom_Direction ent)
    {
        // --- Number of Parameter Control ---

        if (!data.CheckNbParams(num, 2, ach, "direction"))
        {
            return;
        }

        // --- inherited field : name ---

        TCollection_HAsciiString aName = null;
        // szv#4:S4163:12Mar99 `bool stat1 =` not needed
        data.ReadString(num, 1, "name", ach, ref aName);

        // --- own field : directionRatios ---

        double aCoordinatesItem = 0.0;
        int aNSub2 = 0, aNbCoord = 0;
        double[] aXYZ = { 0.0, 0.0, 0.0 };
        if (data.ReadSubList(num, 2, "direction_ratios", ach, ref aNSub2))
        {
            int aNbElements = data.NbParams(aNSub2);
            if (aNbElements > 3)
            {
                ach.AddWarning("More than 3 direction ratios, ignored");
            }
            aNbCoord = Min(aNbElements, 3);
            for (int i2 = 0; i2 < aNbCoord; i2++)
            {
                if (data.ReadReal(aNSub2, i2 + 1, "direction_ratios", ach, ref aCoordinatesItem))
                {
                    aXYZ[i2] = aCoordinatesItem;
                }
            }
        }

        //--- Initialisation of the read entity ---
        if (aNbCoord == 3)
        {
            ent.Init3D(aName, aXYZ[0], aXYZ[1], aXYZ[2]);
        }
        else
        {
            ent.Init2D(aName, aXYZ[0], aXYZ[1]);
        }
    }

    public void WriteStep(StepData_StepWriter SW, StepGeom_Direction ent)
    {
        // --- inherited field name ---

        SW.Send(ent.Name());

        // --- own field : directionRatios ---

        SW.OpenSub();
        for (int i2 = 1; i2 <= ent.NbDirectionRatios(); i2++)
        {
            SW.Send(ent.DirectionRatiosValue(i2));
        }
        SW.CloseSub();
    }

    public void Check(StepGeom_Direction ent, Interface_ShareTool shares, Interface_Check ach)
    {
        int nbVal = ent.NbDirectionRatios();
        int i = 0;
        for (i = 1; i <= nbVal; i++)
        {
            if (Math.Abs(ent.DirectionRatiosValue(i)) >= RealEpsilon())
            {
                break;
            }
        }
        if (i > nbVal)
        {
            ach.AddFail("ERROR: DirectionRatios all 0.0");
        }
    }
